WITH lines AS (SELECT base.id, base.created_at, base.coupon_codes, elem.qty, elem.price, elem.promo FROM carts base LATERAL VIEW OUTER EXPLODE(base.items) t AS elem) SELECT id, created_at, coupon_codes, AVG(qty) OVER (PARTITION BY promo ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS qty_avg_15m, DENSE_RANK() OVER (PARTITION BY promo ORDER BY qty DESC) AS qty_dense_rank FROM lines
